changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_tenant TEXT; v_count BIGINT; BEGIN -- GUC guard: must have a non-empty tenant scope v_tenant := current_setting('nexus.tenant', true); IF v_tenant IS NULL OR v_tenant = '' THEN RAISE EXCEPTION 'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. ' 'Cross-tenant purge is not permitted. Set the nexus.tenant configuration ' 'parameter before calling purge_trash.'; END IF;
-- Step 1: sweep orphaned chunk rows from chunks_384. -- Safety contract: a chunk is sweepable ONLY IF it has at least one manifest row -- AND none of its manifest rows PROTECT it -- a row protects when its owning -- document is LIVE, or TOMBSTONED but still inside the older_than grace window -- (nexus-5da44: matches Step 4's own age predicate exactly, its complement). -- Manifest-less chunks (MCP store_put / nx store put notes that write chunks -- directly without manifest rows) are never swept -- their NOT EXISTS subquery -- is trivially TRUE, so the EXISTS(...manifest row...) gate excludes them. -- RDR-145 deferred scope. DELETE FROM nexus.chunks_384 c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) );
-- Step 2: sweep orphaned chunk rows from chunks_768. DELETE FROM nexus.chunks_768 c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) );
-- Step 3: sweep orphaned chunk rows from chunks_1024. DELETE FROM nexus.chunks_1024 c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) );
-- Step 4: physically delete tombstoned documents older than the threshold. -- fk-001 ON DELETE CASCADE removes catalog_document_chunks, document_aspects, -- document_highlights, and aspect_extraction_queue rows for each deleted doc. -- Unchanged from catalog-003-5. DELETE FROM nexus.catalog_documents WHERE tenant_id = v_tenant AND deleted_at IS NOT NULL AND deleted_at <= NOW() - older_than;
GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END; $$

rollback.sql:
CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_tenant TEXT; v_count BIGINT; BEGIN v_tenant := current_setting('nexus.tenant', true); IF v_tenant IS NULL OR v_tenant = '' THEN RAISE EXCEPTION 'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. ' 'Cross-tenant purge is not permitted. Set the nexus.tenant configuration ' 'parameter before calling purge_trash.'; END IF;
DELETE FROM nexus.chunks_384 c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL );
DELETE FROM nexus.chunks_768 c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL );
DELETE FROM nexus.chunks_1024 c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NULL );
DELETE FROM nexus.catalog_documents WHERE tenant_id = v_tenant AND deleted_at IS NOT NULL AND deleted_at <= NOW() - older_than;
GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END; $$
